/// Converts between Roman numerals and integers.
///
/// # Arguments
/// * `input` - A string slice that is either a Roman numeral (e.g., "XIV")
///             or a decimal integer string (e.g., "14").
///
/// # Returns
/// `Ok(String)` with the converted value, or `Err` if the input is invalid.
///
/// # Examples
/// ```
/// let result = validate_schema("XIV").unwrap();
/// assert_eq!(result, "14");
///
/// let result = validate_schema("14").unwrap();
/// assert_eq!(result, "XIV");
/// ```
pub fn validate_schema(input: &str) -> Result<String, String> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return Err("empty input".to_string());
    }

    if trimmed.chars().all(|c| c.is_ascii_digit()) && !trimmed.starts_with('0') {
        // Input looks like an integer — convert to Roman numeral.
        let n: u32 = trimmed
            .parse()
            .map_err(|_| format!("invalid integer: {trimmed}"))?;
        int_to_roman(n).map(|r| r.to_string())
    } else {
        // Assume Roman numeral — convert to integer.
        roman_to_int(trimmed).map(|n| n.to_string())
    }
}

// ---------------------------------------------------------------------------
// Roman numeral ↔ integer helpers
// ---------------------------------------------------------------------------

const ROMAN_VALUES: &[(u32, &str)] = &[
    (1000, "M"),
    (900, "CM"),
    (500, "D"),
    (400, "CD"),
    (100, "C"),
    (90, "XC"),
    (50, "L"),
    (40, "XL"),
    (10, "X"),
    (9, "IX"),
    (5, "V"),
    (4, "IV"),
    (1, "I"),
];

fn int_to_roman(mut n: u32) -> Result<String, String> {
    if n == 0 {
        return Err("zero has no Roman numeral representation".to_string());
    }
    if n > 3999 {
        return Err(format!("value {n} exceeds maximum representable (3999)"));
    }

    let mut result = String::new();
    for &(value, symbol) in ROMAN_VALUES {
        while n >= value {
            result.push_str(symbol);
            n -= value;
        }
    }
    Ok(result)
}

fn roman_to_int(s: &str) -> Result<u32, String> {
    if s.is_empty() {
        return Err("empty Roman numeral".to_string());
    }

    let upper = s.to_ascii_uppercase();
    let bytes = upper.as_bytes();

    // Map a single Roman character to its numeric value.
    fn char_value(c: u8) -> Option<u32> {
        match c {
            b'I' => Some(1),
            b'V' => Some(5),
            b'X' => Some(10),
            b'L' => Some(50),
            b'C' => Some(100),
            b'D' => Some(500),
            b'M' => Some(1000),
            _ => None,
        }
    }

    // Validate characters.
    for &b in bytes {
        if char_value(b).is_none() {
            return Err(format!("invalid Roman character: '{}'", b as char));
        }
    }

    // Walk left-to-right: if a smaller value precedes a larger one, subtract it.
    let mut total: u32 = 0;
    let len = bytes.len();

    for i in 0..len {
        let val = char_value(bytes[i]).unwrap();
        let next_val = if i + 1 < len {
            char_value(bytes[i + 1]).unwrap()
        } else {
            0
        };

        if val < next_val {
            // Subtractive pair — must be one of: IV, IX, XL, XC, CD, CM.
            if !matches!(
                (val, next_val),
                (1, 5)
                    | (1, 10)
                    | (10, 50)
                    | (10, 100)
                    | (100, 500)
                    | (100, 1000)
            ) {
                return Err(format!(
                    "invalid subtractive pair: {}{}",
                    bytes[i] as char,
                    bytes[i + 1] as char
                ));
            }
            total = total.wrapping_sub(val);
        } else {
            total = total.wrapping_add(val);
        }
    }

    // Verify the result round-trips to the canonical form.
    let canonical = int_to_roman(total)?;
    if canonical != upper {
        return Err(format!(
            "non-canonical Roman numeral: expected {canonical}, got {upper}"
        ));
    }

    Ok(total)
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    // ---- Roman → Integer ---------------------------------------------------

    #[test]
    fn test_basic_symbols() {
        assert_eq!(roman_to_int("I").unwrap(), 1);
        assert_eq!(roman_to_int("V").unwrap(), 5);
        assert_eq!(roman_to_int("X").unwrap(), 10);
        assert_eq!(roman_to_int("L").unwrap(), 50);
        assert_eq!(roman_to_int("C").unwrap(), 100);
        assert_eq!(roman_to_int("D").unwrap(), 500);
        assert_eq!(roman_to_int("M").unwrap(), 1000);
    }

    #[test]
    fn test_additive_combinations() {
        assert_eq!(roman_to_int("III").unwrap(), 3);
        assert_eq!(roman_to_int("VII").unwrap(), 7);
        assert_eq!(roman_to_int("XIII").unwrap(), 13);
        assert_eq!(roman_to_int("CLX").unwrap(), 160);
        assert_eq!(roman_to_int("MDCLXVI").unwrap(), 1666);
    }

    #[test]
    fn test_subtractive_notation() {
        assert_eq!(roman_to_int("IV").unwrap(), 4);
        assert_eq!(roman_to_int("IX").unwrap(), 9);
        assert_eq!(roman_to_int("XL").unwrap(), 40);
        assert_eq!(roman_to_int("XC").unwrap(), 90);
        assert_eq!(roman_to_int("CD").unwrap(), 400);
        assert_eq!(roman_to_int("CM").unwrap(), 900);
    }

    #[test]
    fn test_complex_numbers() {
        assert_eq!(roman_to_int("XIV").unwrap(), 14);
        assert_eq!(roman_to_int("XLII").unwrap(), 42);
        assert_eq!(roman_to_int("XCIX").unwrap(), 99);
        assert_eq!(roman_to_int("CDXLIV").unwrap(), 444);
        assert_eq!(roman_to_int("MCMXCIX").unwrap(), 1999);
        assert_eq!(roman_to_int("MMXXVI").unwrap(), 2026);
        assert_eq!(roman_to_int("MMMCMXCIX").unwrap(), 3999);
    }

    #[test]
    fn test_case_insensitive() {
        assert_eq!(roman_to_int("xiv").unwrap(), 14);
        assert_eq!(roman_to_int("mcmxcix").unwrap(), 1999);
        assert_eq!(roman_to_int("MdClXvI").unwrap(), 1666);
    }

    // ---- Integer → Roman ---------------------------------------------------

    #[test]
    fn test_int_to_roman_basic() {
        assert_eq!(int_to_roman(1).unwrap(), "I");
        assert_eq!(int_to_roman(4).unwrap(), "IV");
        assert_eq!(int_to_roman(9).unwrap(), "IX");
        assert_eq!(int_to_roman(42).unwrap(), "XLII");
        assert_eq!(int_to_roman(1999).unwrap(), "MCMXCIX");
        assert_eq!(int_to_roman(3999).unwrap(), "MMMCMXCIX");
    }

    #[test]
    fn test_int_to_roman_boundaries() {
        assert_eq!(int_to_roman(5).unwrap(), "V");
        assert_eq!(int_to_roman(10).unwrap(), "X");
        assert_eq!(int_to_roman(50).unwrap(), "L");
        assert_eq!(int_to_roman(100).unwrap(), "C");
        assert_eq!(int_to_roman(500).unwrap(), "D");
        assert_eq!(int_to_roman(1000).unwrap(), "M");
    }

    #[test]
    fn test_int_to_roman_zero_and_overflow() {
        assert!(int_to_roman(0).is_err());
        assert!(int_to_roman(4000).is_err());
    }

    // ---- validate_schema (auto-detect direction) ---------------------------

    #[test]
    fn test_validate_schema_roman_to_int() {
        assert_eq!(validate_schema("XIV").unwrap(), "14");
        assert_eq!(validate_schema("MCMXCIX").unwrap(), "1999");
        assert_eq!(validate_schema("MMMCMXCIX").unwrap(), "3999");
    }

    #[test]
    fn test_validate_schema_int_to_roman() {
        assert_eq!(validate_schema("14").unwrap(), "XIV");
        assert_eq!(validate_schema("1999").unwrap(), "MCMXCIX");
        assert_eq!(validate_schema("42").unwrap(), "XLII");
    }

    #[test]
    fn test_validate_schema_empty_input() {
        assert!(validate_schema("").is_err());
        assert!(validate_schema("   ").is_err());
    }

    #[test]
    fn test_validate_schema_invalid_roman() {
        assert!(validate_schema("IIII").is_err()); // non-canonical
        assert!(validate_schema("VV").is_err()); // non-canonical
        assert!(validate_schema("ABC").is_err()); // invalid chars
    }

    #[test]
    fn test_validate_schema_invalid_integer() {
        assert!(validate_schema("0").is_err()); // leading zero / no Roman for 0
        assert!(validate_schema("4000").is_err()); // exceeds 3999
    }

    // ---- Round-trip property test ------------------------------------------

    #[test]
    fn test_round_trip_integers() {
        for n in 1..=3999 {
            let roman = int_to_roman(n).unwrap();
            let back = roman_to_int(&roman).unwrap();
            assert_eq!(n, back, "round-trip failed for {n} ({roman})");
        }
    }

    #[test]
    fn test_round_trip_validate_schema() {
        for n in (1..=3999).step_by(37) {
            let via_roman = validate_schema(&n.to_string()).unwrap();
            let back = validate_schema(&via_roman).unwrap();
            assert_eq!(back, n.to_string(), "round-trip failed for {n}");
        }
    }
}

